	private static readonly LinkedList<string> _recent = new LinkedList<string>();

	private static readonly HashSet<string> _recentSet = new HashSet<string>();

	public static Func<string, string> LeaderNameOf;

	private static Dictionary<string, string[]> P(params (string key, string[] lines)[] pools)
	{
		return pools.ToDictionary(((string key, string[] lines) p) => p.key, ((string key, string[] lines) p) => p.lines);
	}

	public static string Pick(string situation, string factionId, Personality? temper, Random rng, IDictionary<string, string> tokens = null, bool leaderOut = false)
	{
		if (!Lines.TryGetValue(situation, out var value))
		{
			return null;
		}
		List<string> list = new List<string>();
		if (!string.IsNullOrEmpty(factionId) && value.TryGetValue(factionId, out var value2))
		{
			list.AddRange(value2);
			list.AddRange(value2);
		}
		if (temper.HasValue && value.TryGetValue(temper.Value.ToString(), out var value3))
		{
			list.AddRange(value3);
		}
		if (value.TryGetValue("", out var value4))
		{
			list.AddRange(value4);
		}
		string text = ((!string.IsNullOrEmpty(factionId) && LeaderNameOf != null) ? LeaderNameOf(factionId) : null);
		if (leaderOut || (text == null && LeaderNameOf != null && !string.IsNullOrEmpty(factionId)))
		{
			list.RemoveAll((string l) => l.Contains("COLM") || l.Contains("MR BRONTE") || l.Contains("THE GENERAL") || l.Contains("FAVOURS") || l.Contains("{LEADER}"));
		}
		if (list.Count == 0)
		{
			return null;
		}
		List<string> list2 = list.Where((string l) => !_recentSet.Contains(l)).ToList();
		string text2 = ((list2.Count > 0) ? list2 : list)[rng.Next((list2.Count > 0) ? list2.Count : list.Count)];
		_recent.AddLast(text2);
		_recentSet.Add(text2);
		while (_recent.Count > 80)
		{
			_recentSet.Remove(_recent.First.Value);
			_recent.RemoveFirst();
		}
		if (tokens != null)
		{
			foreach (KeyValuePair<string, string> token in tokens)
			{
				text2 = text2.Replace("{" + token.Key.ToUpperInvariant() + "}", (token.Value ?? "").ToUpperInvariant());
			}
		}
		if (text != null)
		{
			string[] array = text.Split(' ');
			string text3 = ((array.Length > 1 && array[0].EndsWith(".")) ? array[array.Length - 1] : array[0]).ToUpperInvariant();
			if (factionId == "odriscoll" && !text.Contains("Colm"))
			{
				text2 = text2.Replace("COLM", text3);
			}
			if (factionId == "lemoyneraiders")
			{
				text2 = text2.Replace("THE GENERAL", text3);
			}
			if (factionId == "bronte" && !text.Contains("Bronte"))
			{
				text2 = text2.Replace("MR BRONTE'S", text3 + "'S").Replace("MR BRONTE", text3);
			}
		}
		return text2;
	}
